const DEMO={lat:38.46,lon:-98.25,name:'Central Kansas demo field',method:'Demonstration point'};const state={loc:JSON.parse(localStorage.getItem('fs-location')||'null')||DEMO,unit:localStorage.getItem('fs-unit')||'metric',map:null,marker:null,nasa:null,abort:null,data:null};const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],set=(s,v)=>{const e=$(s);if(e)e.textContent=v};const fmt=(n,a)=>Math.abs(n).toFixed(4)+'° '+(n>=0?(a?'N':'E'):(a?'S':'W'));function page(id){$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+id));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));set('#crumbPage',id.toUpperCase());if(id==='home'&&state.map)setTimeout(()=>state.map.invalidateSize(),100);scrollTo(0,0);if($('#moreDialog').open)$('#moreDialog').close()}function init(){$$('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));$$('[data-open]').forEach(b=>b.onclick=()=>page(b.dataset.open));$('#mobileMore').onclick=$('#menuToggle').onclick=()=>$('#moreDialog').showModal();$('#closeMore').onclick=()=>$('#moreDialog').close();$('#helpBtn').onclick=()=>page('assistant');try{state.map=L.map('map').setView([state.loc.lat,state.loc.lon],6);L.control.zoom({position:'bottomright'}).addTo(state.map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(state.map);state.map.on('click',e=>loc({lat:e.latlng.lat,lon:e.latlng.lng,name:'Map-selected point',method:'Map click'}))}catch(e){console.warn(e)}$('#searchForm').onsubmit=e=>{e.preventDefault();search($('#query').value)};$('#coordOpen').onclick=$('#changeLocation').onclick=()=>$('#coordDialog').showModal();$('#useCoords').onclick=e=>{e.preventDefault();loc({lat:+$('#latInput').value,lon:+$('#lonInput').value,name:'Coordinate-selected point',method:'Coordinates entered'});$('#coordDialog').close()};$('#resetLocation').onclick=()=>loc(DEMO);$('#nasa').onchange=nasaLayer;$('#refresh').onclick=load;$$('[data-aim]').forEach(b=>b.onclick=()=>aim(b.dataset.aim));$('#recalculate').onclick=()=>{set('#cropOne',$('#cropSelect').value);set('#cropTwo',$('#cropSelect2').value);set('#cropScore','78/100');toast('Rotation scenario updated')};$('#calculateProfit').onclick=profit;['#yieldInput','#priceInput','#inputCost','#otherCost','#profitCrop'].forEach(s=>$(s).onchange=profit);$('#sampleToggle').onclick=()=>$('#sampleForm').hidden=!$('#sampleForm').hidden;$('#saveSample').onclick=saveSample;$('#downloadReport').onclick=report;$('#export').onclick=report;$('#chatForm').onsubmit=e=>{e.preventDefault();ask($('#chatInput').value)};$$('.suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));$('#unitSetting').value=state.unit;$('#unitSetting').onchange=e=>{state.unit=e.target.value;localStorage.setItem('fs-unit',state.unit);if(state.data)render(state.data)};$('#themeSetting').onchange=e=>document.body.classList.toggle('night',e.target.value==='night');$('#restoreDemo').onclick=()=>loc(DEMO);$('#clearData').onclick=()=>{localStorage.removeItem('fs-samples');localStorage.removeItem('fs-location');loc(DEMO);samples()};$('#rememberSetting').onchange=e=>{if(!e.target.checked)localStorage.removeItem('fs-location')};samples();paint();load();profit()}function loc(x){if(!Number.isFinite(+x.lat)||!Number.isFinite(+x.lon)||Math.abs(x.lat)>90||Math.abs(x.lon)>180)return toast('Enter valid coordinates');state.loc={...x,lat:+x.lat,lon:+x.lon};if($('#rememberSetting').checked)localStorage.setItem('fs-location',JSON.stringify(state.loc));if(state.marker)state.marker.remove();if(state.map){state.marker=L.circleMarker([x.lat,x.lon],{radius:8,color:'#fff',weight:3,fillColor:'#d9764d',fillOpacity:1}).addTo(state.map);state.map.flyTo([x.lat,x.lon],7)}paint();load()}function paint(){set('#place',state.loc.name);set('#mapLocation',state.loc.name);set('#placePill',state.loc.name);set('#coordinates',fmt(state.loc.lat,1)+' · '+fmt(state.loc.lon,0));set('#reportCoords',state.loc.lat.toFixed(4)+', '+state.loc.lon.toFixed(4));set('#reportMethod',state.loc.method);set('#reportName',state.loc.name);if(state.map&&!state.marker)state.marker=L.circleMarker([state.loc.lat,state.loc.lon],{radius:8,color:'#fff',weight:3,fillColor:'#d9764d',fillOpacity:1}).addTo(state.map)}async function load(){state.abort?.abort();state.abort=new AbortController;try{let q=new URLSearchParams({latitude:state.loc.lat,longitude:state.loc.lon,current:'temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m,soil_moisture_0_to_1cm',daily:'temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,et0_fao_evapotranspiration',timezone:'auto',forecast_days:3}),r=await fetch('https://api.open-meteo.com/v1/forecast?'+q,{signal:state.abort.signal});if(!r.ok)throw Error('Provider request failed');state.data=await r.json();render(state.data)}catch(e){if(e.name==='AbortError')return;set('#homeWeather','Weather unavailable');set('#forecastCondition','Forecast unavailable');set('#weatherStatus','UNAVAILABLE');toast('Live data unavailable')}}function render(d){let c=d.current,day=d.daily,mo=c.soil_moisture_0_to_1cm,imp=state.unit==='imperial',t=x=>isFinite(x)?Math.round(imp?x*9/5+32:x)+'°'+(imp?'F':'C'):'—',r=x=>isFinite(x)?(imp?(x/25.4).toFixed(2)+' in':x.toFixed(1)+' mm'):'—';set('#homeTemp',t(c.temperature_2m));set('#homeWeather',wx(c.weather_code));set('#homeFeels','Feels '+t(c.apparent_temperature)+' · humidity '+c.relative_humidity_2m+'%');set('#homeRain',r(day.precipitation_sum[1]));set('#homeRainNote','Tomorrow · '+day.precipitation_probability_max[1]+'% probability');set('#homeSoil',isFinite(mo)?(mo*100).toFixed(0)+'%':'—');set('#soil',isFinite(mo)?(mo*100).toFixed(0)+'%':'—');set('#weather',t(c.temperature_2m)+' · '+wx(c.weather_code));set('#weatherDesc','Feels '+t(c.apparent_temperature)+', humidity '+c.relative_humidity_2m+'%, wind '+Math.round(c.wind_speed_10m)+' km/h.');set('#weatherStatus','AVAILABLE');set('#forecastCondition',wx(c.weather_code)+' · '+t(c.temperature_2m));set('#forecastMeta','Current model analysis · '+c.time+' · '+d.timezone);set('#weatherBig',t(c.temperature_2m));set('#weatherDetail',wx(c.weather_code));set('#feels',t(c.apparent_temperature));set('#humidity',c.relative_humidity_2m+'%');set('#wind',c.wind_speed_10m+' km/h');set('#weatherValid',c.time);set('#waterRain',r(day.precipitation_sum[0]));set('#waterRainText',day.precipitation_probability_max[0]+'% forecast probability');set('#waterEt',r(day.et0_fao_evapotranspiration[0]));set('#waterMoisture',isFinite(mo)?(mo*100).toFixed(0)+'%':'—');set('#soilProfileValue',isFinite(mo)?(mo*100).toFixed(0)+'%':'—');set('#soilProfileText','Modeled water content for shallow 0–1 cm layer. Not total root-zone water.');set('#elevation',isFinite(d.elevation)?Math.round(d.elevation)+' m · model grid':'Unavailable');set('#forecastTime','Valid '+c.time);set('#reportRetrieved',new Date().toLocaleString());$('#forecast').innerHTML=day.time.map((v,i)=>'<div><small>'+new Date(v+'T12:00').toLocaleDateString(undefined,{weekday:'short'})+'</small><b>'+t(day.temperature_2m_max[i])+'</b><span>'+r(day.precipitation_sum[i])+' rain</span></div>').join('');$('#weatherForecast').innerHTML=day.time.map((v,i)=>'<div><small>'+v+'</small><b>'+t(day.temperature_2m_max[i])+'</b><p>Low '+t(day.temperature_2m_min[i])+' · Rain '+r(day.precipitation_sum[i])+'</p></div>').join('');$('#tempChart').innerHTML=day.temperature_2m_max.map(v=>'<i style="height:'+Math.max(20,(v+5)*3)+'%"><span>'+Math.round(v)+'°</span></i>').join('');set('#reportRows','');$('#reportRows').innerHTML='<tr><td>Weather</td><td>'+t(c.temperature_2m)+'</td><td>Model analysis</td><td>Open-Meteo</td></tr><tr><td>Rain</td><td>'+r(day.precipitation_sum[0])+'</td><td>Forecast</td><td>Open-Meteo</td></tr><tr><td>Moisture</td><td>'+(isFinite(mo)?(mo*100).toFixed(0)+'%':'—')+'</td><td>Model · 0–1 cm</td><td>Open-Meteo</td></tr>';set('#evidenceList','');$('#evidenceList').innerHTML='<p>Weather: '+t(c.temperature_2m)+' · '+c.time+'</p><p>Surface moisture: '+(isFinite(mo)?(mo*100).toFixed(0)+'%':'unavailable')+' · 0–1 cm</p><p>Location: '+state.loc.name+'</p>'}function wx(c){return({0:'Clear sky',1:'Mostly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',61:'Light rain',63:'Rain',65:'Heavy rain',80:'Showers',95:'Thunderstorm'})[c]||'Conditions available'}async function search(x){if(x.length<2)return;$('#results').textContent='Searching…';try{let d=await(await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(x)+'&count=5&language=en')).json(),a=d.results||[];$('#results').innerHTML=a.map((z,i)=>'<button data-i="'+i+'">'+z.name+', '+(z.country||'')+'<small>'+z.latitude.toFixed(3)+', '+z.longitude.toFixed(3)+'</small></button>').join('')||'No results';$$('#results button').forEach(b=>b.onclick=()=>{let z=a[b.dataset.i];$('#results').innerHTML='';loc({lat:z.latitude,lon:z.longitude,name:z.name+', '+z.country,method:'Place search'})})}catch{$('#results').textContent='Search unavailable'}}function nasaLayer(e){if(e.target.checked){let d=new Date(Date.now()-7*864e5).toISOString().slice(0,10);state.nasa=L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/MODIS_Terra_CorrectedReflectance_TrueColor/default/'+d+'/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg',{maxZoom:9,opacity:.7,attribution:'NASA GIBS'}).addTo(state.map);set('#layerNote','NASA MODIS · '+d)}else if(state.nasa){state.map.removeLayer(state.nasa);state.nasa=null;set('#layerNote','OpenStreetMap')}}function aim(a){let v={soil:[82,'Soybean','Sorghum','Legume integration supports soil cover.'],water:[76,'Sorghum','Chickpea','Drought-tolerant options are favored in this qualitative scenario.'],risk:[86,'Sunflower','Cowpea','A broader mix diversifies crop family and seasonal timing.']}[a];$$('[data-aim]').forEach(b=>b.classList.toggle('selected',b.dataset.aim===a));set('#cropOne',v[1]);set('#cropTwo',v[2]);set('#cropScore',v[0]+'/100');set('#alignment',v[0]);set('#alignmentText',v[3])}function profit(){let y=+$('#yieldInput').value||0,p=+$('#priceInput').value||0,c=(+$('#inputCost').value||0)+(+$('#otherCost').value||0),rev=y*p,m=rev-c,f=n=>'$'+Math.round(n).toLocaleString();set('#margin',f(m));set('#gross',f(m));set('#homeProfit',f(m));set('#revenue',f(rev));set('#costTotal',f(c));set('#grossCrop',$('#profitCrop').value+' · entered values');set('#sensitivityText','A 10% price drop changes margin by '+f(-rev*.1)+' per acre.');$('#profitBars').innerHTML=[rev,c,Math.max(0,m)].map(v=>'<i style="height:'+Math.max(12,Math.min(100,v/Math.max(1,rev)*100))+'%"></i>').join('')}function samples(){let a=JSON.parse(localStorage.getItem('fs-samples')||'[]');$('#sampleList').innerHTML=a.map((x,i)=>'<p>'+x.name+' · '+x.date+' · pH '+(x.ph||'—')+' · C '+(x.carbon||'—')+'% <button data-del="'+i+'">Remove</button></p>').join('');$$('[data-del]').forEach(b=>b.onclick=()=>{a.splice(+b.dataset.del,1);localStorage.setItem('fs-samples',JSON.stringify(a));samples()})}function saveSample(){let x={name:$('#sampleName').value||'Soil sample',ph:$('#samplePh').value,carbon:$('#sampleCarbon').value,date:new Date().toLocaleDateString()};if(!x.ph&&!x.carbon)return toast('Enter a measurement');let a=JSON.parse(localStorage.getItem('fs-samples')||'[]');a.push(x);localStorage.setItem('fs-samples',JSON.stringify(a));samples();toast('Saved on this device')}function report(){let x='FIELDSHIFT SESSION REPORT\nLocation: '+state.loc.name+'\nCoordinates: '+state.loc.lat+', '+state.loc.lon+'\nGenerated: '+new Date().toISOString()+'\nWeather: '+($('#weather').textContent||'Unavailable')+'\nGross margin scenario: '+$('#margin').textContent+' per acre\nRotation: '+$('#cropOne').textContent+' → '+$('#cropTwo').textContent+'\n\nLimitations: selected point is not a field polygon; forecasts and model values are not direct point measurements; profit uses user-entered assumptions; rotation is illustrative.';let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([x],{type:'text/plain'}));a.download='fieldshift-report.txt';a.click();URL.revokeObjectURL(a.href)}function ask(q){if(!q)return;let box=$('#chatMessages'),u=document.createElement('div');u.className='user-msg';u.textContent=q;box.append(u);let l=q.toLowerCase(),mo=state.data?.current?.soil_moisture_0_to_1cm,ans=l.includes('soil')?'The selected point has a '+(isFinite(mo)?(mo*100).toFixed(0)+'%':'currently unavailable')+' model estimate for just the top 0–1 cm. It is not a lab test or full root-zone measurement. A soil sample would help with pH, texture, and carbon.' :l.includes('profit')?'The margin estimate is '+$('#margin').textContent+' per acre: entered yield times entered price minus the two entered cost fields. Land rent, financing, taxes, and overhead are excluded. I do not fetch live commodity prices.' :l.includes('water')||l.includes('rain')?'Rain forecast and shallow moisture are different signals. I have no reservoir, groundwater, or irrigation access information for this point.' :'The current path is '+$('#cropOne').textContent+' followed by '+$('#cropTwo').textContent+'. The scenario uses broad crop traits; it lacks field history, local varieties, pest data, lab soil results, and local planting guidance.';let a=document.createElement('div');a.className='assistant-msg';a.textContent=ans;let s=document.createElement('small');s.textContent='Based on this session · verify with local measurements and expertise.';a.append(s);box.append(a);$('#chatInput').value='';box.scrollTop=box.scrollHeight}function toast(t){set('#toast',t);$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}document.addEventListener('DOMContentLoaded',init);
